      const reader = new FileReader();
      reader.onload = () => { state.cover.logoDataUrl = String(reader.result || ''); saveState(); renderSlide(); toast('Logo de couverture remplacé.'); };
      reader.onerror = () => toast('Impossible de lire cette image.');
