  function fitPresentationSlide() {
    if (!document.body.classList.contains('presentation-mode')) return;
    const tabsBar = document.querySelector('.tabs');
    const tabsHeight = tabsBar ? Math.max(44, tabsBar.getBoundingClientRect().height) : 58;
    const scale = Math.max(0.2, Math.min(window.innerWidth / 1600, (window.innerHeight - tabsHeight) / 900));
    slideStage.style.setProperty('width', `${1600 * scale}px`, 'important');
    slideStage.style.setProperty('height', `${900 * scale}px`, 'important');
    slide.style.setProperty('transform', `scale(${scale})`, 'important');
    slide.style.transformOrigin = 'top left';
  }

  if (presentationBtn) {
    presentationBtn.addEventListener('click', async () => {
      document.body.classList.add('presentation-mode');
      try { if (document.fullscreenElement !== document.getElementById('appShell')) await document.getElementById('appShell').requestFullscreen(); } catch (e) {}
      requestAnimationFrame(fitPresentationSlide);
    });
    document.addEventListener('fullscreenchange', () => {
      if (!document.fullscreenElement) {
        document.body.classList.remove('presentation-mode');
        slideStage.style.removeProperty('width'); slideStage.style.removeProperty('height'); slide.style.removeProperty('transform');
        if (previewAutoFit) requestAnimationFrame(fitPreviewSlide); else setZoom(num(zoomRange.value));
      } else requestAnimationFrame(fitPresentationSlide);
    });
    window.addEventListener('resize', () => { if (document.body.classList.contains('presentation-mode')) fitPresentationSlide(); else schedulePreviewFit(); });
  }

  async function openWorkbookPrintDialog() {
    // Ouvre la fenêtre immédiatement (dans le geste utilisateur), puis injecte
    // chaque slide sous forme d'URL Blob. Cela évite de passer des dizaines de
    // mégaoctets de PNG encodés en base64 à document.write(), source du
    // "Failed to execute 'write' on 'Document'" dans certains navigateurs.
    const printWindow = window.open('', '_blank', 'width=1400,height=900,resizable=yes,scrollbars=yes');
    if (!printWindow) throw new Error('Le navigateur a bloqué la fenêtre d’impression. Autorise les pop-up pour ce site.');

    // Petit squelette uniquement : aucun gros contenu n'est envoyé à document.write.
    printWindow.document.open();
    printWindow.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Prestaterre - Classeur</title></head><body></body></html>`);
    printWindow.document.close();

    const doc = printWindow.document;
    const style = doc.createElement('style');
    style.textContent = `
      html,body{margin:0!important;padding:0!important;background:#f2f4f3!important;font-family:Arial,Helvetica,sans-serif!important;color:#173b3f;}
      .prep{min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:40px;box-sizing:border-box;}
      .prep-card{background:#fff;border:1px solid #cbdad4;border-radius:18px;padding:30px 38px;box-shadow:0 16px 40px rgba(0,0,0,.08);}
      .prep-title{font-size:24px;font-weight:800;color:#06402B;margin-bottom:10px;}
      .prep-status{font-size:15px;color:#607277;}
      .print-root{display:none;background:#fff;}
      .print-page{width:1600px;height:900px;overflow:hidden;page-break-after:always;break-after:page;background:#fff;position:relative;display:flex;align-items:center;justify-content:center;}
      .print-page:last-child{page-break-after:auto;break-after:auto;}
      .print-page img{display:block;width:1600px;height:900px;object-fit:contain;margin:0;padding:0;border:0;}
      @page{size:16.666667in 9.375in;margin:0;}
      @media print{
        html,body{margin:0!important;padding:0!important;background:#fff!important;}
        .prep{display:none!important;}
        .print-root{display:block!important;}
        .print-page{width:1600px!important;height:900px!important;page-break-after:always!important;break-after:page!important;overflow:hidden!important;}
        .print-page:last-child{page-break-after:auto!important;break-after:auto!important;}
        .print-page img{width:1600px!important;height:900px!important;object-fit:contain!important;}
        *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;}
      }
    `;
    doc.head.appendChild(style);

    const prep = doc.createElement('div');
    prep.className = 'prep';
    prep.innerHTML = '<div class="prep-card"><div class="prep-title">Préparation du classeur</div><div class="prep-status" id="prepStatus">Initialisation…</div></div>';
    doc.body.appendChild(prep);
    const root = doc.createElement('div');
    root.className = 'print-root';
    doc.body.appendChild(root);

    const originalTab = activeTab;
    const orderedTabs = [...state.presentation.order];
    const objectUrls = [];

    try {
      saveTabData(activeTab);
      for (let i = 0; i < orderedTabs.length; i += 1) {
        activateTab(orderedTabs[i], { scroll:false });
        await waitForSlideAssets();
        await waitForPaintFrames(2);
        const status = doc.getElementById('prepStatus');
        if (status) status.textContent = `Rendu de la slide ${i + 1} / ${orderedTabs.length} — ${tabLabel(activeTab)}`;

        // Même moteur que PNG 4K = rendu visuel identique à l'export PNG validé.
        const png = await safeSlidePngBlob();
        const url = URL.createObjectURL(png);
        objectUrls.push(url);

        const page = doc.createElement('section');
        page.className = 'print-page';
        page.setAttribute('aria-label', tabLabel(activeTab));
        const img = doc.createElement('img');
        img.src = url;
        img.alt = tabLabel(activeTab);
        page.appendChild(img);
        root.appendChild(page);

        await new Promise(resolve => setTimeout(resolve, 0));
      }
    } catch (error) {
      const status = doc.getElementById('prepStatus');
      if (status) status.textContent = `Erreur sur ${tabLabel(activeTab)} : ${error && error.message ? error.message : error}`;
      throw error;
    } finally {
      activateTab(originalTab, { scroll:false });
    }

    const status = doc.getElementById('prepStatus');
    if (status) status.textContent = 'Classeur prêt — ouverture de la fenêtre d’impression…';

    // Attend réellement le décodage des images avant d'ouvrir le dialogue.
    const images = [...root.querySelectorAll('img')];
    await Promise.all(images.map(img => {
      if (img.complete && img.naturalWidth) return img.decode ? img.decode().catch(()=>{}) : Promise.resolve();
      return new Promise(resolve => {
        const done = () => resolve();
        img.addEventListener('load', done, {once:true});
        img.addEventListener('error', done, {once:true});
        setTimeout(done, 12000);
      });
    }));

    prep.style.display = 'none';
    root.style.display = 'block';
    await new Promise(resolve => setTimeout(resolve, 250));
    printWindow.focus();
    printWindow.print();

    // Les Blob URLs restent valides le temps que l'aperçu d'impression les lise.
    setTimeout(() => objectUrls.forEach(url => URL.revokeObjectURL(url)), 120000);
  }

