  function dataDisconnect(){const wasConnected=dataRuntime.connected;dataRuntime.connected=false;if(wasConnected)dataRestoreManual();dataRuntime.mode='manual';dataRuntime.sourceUrl='';dataRuntime.sourceTab='OPERATIONS';dataRuntime.zone123Status=null;dataRuntime.sourceOperations=[];dataRuntime.sourceMeta=null;dataRuntime.operations=[];dataRuntime.filtered=[];localStorage.removeItem(DATA_SOURCE_STORAGE_KEY);dataUpdateBadge();dataUpdateFilterUI();renderControls();renderSlide();dataFeedback('Mode manuel restauré.');toast('Mode manuel restauré.');try{window.dispatchEvent(new CustomEvent('newosb:datachange',{detail:window.NEWOSB_ENGINE?.getRuntime?.()}));}catch{}}
